__global__ void shared_mem_reduction_tiled(const float* __restrict__ in, float* __restrict__ out, int n) {
    extern __shared__ float sdata[];

    int tid = threadIdx.x;
    int bid = blockIdx.x;
    int i = bid * blockDim.x * 2 + tid;

    // Load two elements per thread
    float val1 = (i < n) ? in[i] : 0.0f;
    float val2 = (i + blockDim.x < n) ? in[i + blockDim.x] : 0.0f;
    float sum = val1 + val2;

    sdata[tid] = sum;
    __syncthreads();

    // Tree reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) out[bid] = sdata[0];
}

__global__ void strided_read_write(const float* __restrict__ in, float* __restrict__ out, int n, int stride) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n / stride) out[i * stride] = in[i * stride];
}

__global__ void histogram_global(const int* __restrict__ in, int* __restrict__ hist, int n, int nbins) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        int b = in[i] % nbins;
        if (b < 0) b += nbins;
        atomicAdd(&hist[b], 1);
    }
}

__global__ void shared_mem_bank_conflict_1way(float* out, int n) {
    __shared__ float sdata[32 * 33];  // 33 elements per warp = 1-way bank conflict

    int tid = threadIdx.x;
    int lane = tid % 32;
    int warp = tid / 32;

    // Each thread writes to consecutive banks (no conflict)
    sdata[warp * 33 + lane] = lane * 1.0f;
    __syncthreads();

    // Each thread reads from next element (1-way conflict within warp)
    out[blockIdx.x * blockDim.x + tid] = sdata[warp * 33 + (lane + 1) % 32];
}

__global__ void scatter_write(const float* __restrict__ in, float* __restrict__ out, const int* __restrict__ indices, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[indices[i]] = in[i];
}

__global__ void histogram_global(const int* __restrict__ in, int* __restrict__ hist, int n, int nbins) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
