__global__ void reduce_max_block(const float* __restrict__ in, float* __restrict__ out, int n) {
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + tid;

    sdata[tid] = (i < n) ? in[i] : -__FLT_MAX__;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            if (sdata[tid + s] > sdata[tid]) sdata[tid] = sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) out[blockIdx.x] = sdata[0];
}

__global__ void segmented_read(const float* __restrict__ in, float* __restrict__ out, int n, int segment_size) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        int segment = i / segment_size;
        int offset = i % segment_size;
        out[i] = in[segment * segment_size + offset];
    }
}

